public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header Başlık metni.
     * @return Ayrıştırılmış başlık.
     */
    public static String parseHeader(String header) {
        String regex = "^[a-zA-Z0-9 ]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        if (matcher.matches()) {
            return header.trim();
        } else {
            throw new IllegalArgumentException("Geçersiz başlık formatı.");
        }
    }

    public static void main(String[] args) {
        String header = "Valid Header 123";
        try {
            String parsedHeader = parseHeader(header);
            System.out.println("Ayrıştırılan Başlık: " + parsedHeader);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}
