import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * מסננת את קלט המשתמש על ידי הסרת תגיות סקריפט.
     * 
     * הפונקציה משתמשת בהחלפת מחרוזות כדי להסיר תגיות <script>.
     * 
     * @param input הקלט למשתמש
     * @return קלט מסונן
     */
    public String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }
        // Regex to find <script> tags
        String scriptRegex = "<script.*?/script>";
        Pattern pattern = Pattern.compile(scriptRegex, Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(input);
        // Remove <script> tags
        return matcher.replaceAll("");
    }
}
