import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Tisztítja a felhasználói bemenetet a <script> tagek eltávolításával.
     * 
     * A függvény karakterlánc helyettesítést használ a <script> tagek eltávolítására.
     */
    public static String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }
        Pattern scriptPattern = Pattern.compile("<script.*?>.*?</script>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
        Matcher matcher = scriptPattern.matcher(input);
        return matcher.replaceAll("");
    }

    public static void main(String[] args) {
        String userInput = "<script>alert('This is a script');</script><p>Hello World!</p>";
        String sanitizedInput = sanitizeInput(userInput);
        System.out.println(sanitizedInput);  // Output: <p>Hello World!</p>
    }
}
