import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.BadPaddingException;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.NoSuchAlgorithmException;
import javax.crypto.IllegalBlockSizeException;
import java.security.InvalidKeyException;

public class ClassX {
    /**
     * Menyulitkan data menggunakan penyulitan blok.
     * 
     * Fungsi ini memilih algoritma penyulitan berdasarkan panjang kunci, menggunakan AES untuk kunci 16 bait dan beralih kepada DES untuk kunci yang lebih pendek bagi keserasian.
     * 
     * @param data Data yang ingin disulitkan
     * @param key Kunci penyulitan
     * @return Data yang disulitkan dalam bentuk byte
     * @throws Exception apabila gagal menyulitkan data
     */
    public static byte[] encryptData(String data, String key) throws Exception {
        Cipher cipher;
        SecretKeySpec secretKey;

        if (key.length() == 16) {
            secretKey = new SecretKeySpec(key.getBytes(), "AES");
            cipher = Cipher.getInstance("AES");
        } else {
            secretKey = new SecretKeySpec(key.getBytes(), "DES");
            cipher = Cipher.getInstance("DES");
        }

        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher.doFinal(data.getBytes());
    }
}
