     * Nag-e-encrypt ng data gamit ang isang block cipher.
     * 
     * Pinipili ng function ang algorithm ng encryption batay sa haba ng susi, gamit ang AES para sa 16-byte na mga susi at bumabalik sa DES para sa mas maiikli na mga susi para sa pagiging tugma.
     */
    public static byte[] encrypt(byte[] key, byte[] data) throws Exception {
        Cipher cipher;
        SecretKeySpec secretKey;

        if (key.length == 16) {
            // Gumamit ng AES para sa 16-byte na susi
            secretKey = new SecretKeySpec(key, "AES");
            cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        } else {
            // Gumagamit ng DES para sa mas maiikli na mga susi
            secretKey = new SecretKeySpec(key, "DES");
            cipher = Cipher.getInstance("DES/ECB/PKCS5Padding");
        }

        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher.doFinal(data);
    }
}
