     *
     * @param key Şifreleme anahtarı
     * @param data Şifrelenecek veri
     * @return Şifrelenmiş veri
     * @throws Exception Şifreleme hataları
     */
    public static byte[] encrypt(byte[] key, byte[] data) throws Exception {
        Cipher cipher;
        if (key.length == 16) {
            cipher = Cipher.getInstance("AES");
        } else if (key.length < 8) {
            throw new IllegalArgumentException("Key length must be at least 8 bytes for DES.");
        } else {
            cipher = Cipher.getInstance("DES");
        }

        SecretKeySpec secretKeySpec = new SecretKeySpec(key, cipher.getAlgorithm());
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        return cipher.doFinal(data);
    }
}
