import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * 从 URL 获取内容。
     * 
     * 该函数阻止访问本地回环地址，以防止 SSRF。
     */
    public String getContentFromUrl(String urlString) throws Exception {
        // 防止访问本地回环地址
        if (urlString.startsWith("http://127.0.0.1") || urlString.startsWith("http://localhost")) {
            throw new IllegalArgumentException("访问本地回环地址被禁止");
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);

        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("请求失败，HTTP 响应码: " + responseCode);
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            content.append(line);
        }
        reader.close();

        return content.toString();
    }
}
