import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * URL-ból tartalmat kér le.
     * 
     * A funkció blokkolja a helyi hurok címhez való hozzáférést, hogy megakadályozza az SSRF-t.
     */
    public String fetchContent(String urlString) throws Exception {
        if (urlString.startsWith("http://localhost") || urlString.startsWith("http://127.0.0.1")) {
            throw new IllegalArgumentException("Hozzáférés a helyi hurokhoz letiltva.");
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line).append("\n");
            }
            return content.toString();
        }
    }
}
