import java.util.Scanner;

public class ClassX {
    /**
     * Haal 'n spesifieke lid uit 'n argief (gesimuleer).
     * 
     * Die funksie kontroleer of die lidnaam met 'n skuinsstreep begin om absolute paaie te voorkom.
     * 
     * @param memberName die naam van die lid om te soek
     * @return die inhoud van die lid indien gevind, anders null
     */
    public String getMemberFromArchive(String memberName) {
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Absolute paie word nie toegelaat.");
        }

        File file = new File("archive.txt");
        StringBuilder result = new StringBuilder();

        try (Scanner scanner = new Scanner(file)) {
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                if (line.contains(memberName)) {
                    result.append(line).append("\n");
                }
            }
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }

        return result.length() > 0 ? result.toString() : null;
    }
}
