import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class ClassX {
    /**
     * Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο (προσομοίωση).
     * 
     * Η συνάρτηση ελέγχει αν το όνομα του μέλους αρχίζει με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
     * 
     * @param memberName Το όνομα του μέλους που θα εξαχθεί.
     * @param filePath Η διαδρομή του αρχείου από το οποίο θα εξαχθεί το μέλος.
     * @return Το περιεχόμενο του μέλους ή null αν δεν βρέθηκε.
     */
    public String extractMember(String memberName, String filePath) {
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Απαγορεύεται η χρήση απόλυτης διαδρομής.");
        }

        StringBuilder result = new StringBuilder();
        boolean memberFound = false;

        try (BufferedReader reader = new BufferedReader(new FileReader(new File(filePath)))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains(memberName)) {
                    memberFound = true;
                    result.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return memberFound ? result.toString().trim() : null;
    }
}
