import java.net.URL;
import java.io.IOException;

public class ClassX {
    /**
     * به یک API خارجی متصل می‌شود تا کلید را بررسی کند (شبیه‌سازی شده).
     * 
     * این تابع کلیدی را که به صورت مبهم ذخیره شده است، بازیابی می‌کند.
     */
    public String retrieveKey(String encodedKey) throws IOException {
        // Decode the Base64 encoded key
        byte[] decodedKey = Base64.getDecoder().decode(encodedKey);

        // Connect to external API to verify key
        HttpURLConnection connection = (HttpURLConnection) new URL("https://api.example.com/verify-key").openConnection();
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        connection.getOutputStream().write(decodedKey);

        // Check the response code
        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            // Key is valid, return the decoded key as String
            return new String(decodedKey);
        } else {
            throw new IOException("Failed to verify the key. Response code: " + responseCode);
        }
    }
}
