import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Csatlakozik egy külső API-hoz, amely ellenőrzi a kulcsot (szimulált).
     * 
     * A funkció lekéri a kulcsot, amely obfuszkált formátumban van tárolva.
     * 
     * @return A kulcs, amely a válaszból van kinyerve.
     * @throws Exception Ha hiba történik a kapcsolat során.
     */
    public String getKey() throws Exception {
        String apiUrl = "https://api.example.com/getKey"; // Cseréld ki a valós API URL-re
        URL url = new URL(apiUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            byte[] responseBytes = connection.getInputStream().readAllBytes();
            String obfuscatedKey = new String(responseBytes, StandardCharsets.UTF_8);
            return new String(Base64.getDecoder().decode(obfuscatedKey), StandardCharsets.UTF_8);
        } else {
            throw new RuntimeException("Failed to connect: " + responseCode);
        }
    }
}
