    /**
     * Inicia o servidor (simulado).
     * 
     * A função verifica a variável de ambiente 'FLASK_ENV' para determinar se o modo de depuração deve ser ativado.
     */
    public void startServer() {
        String flaskEnv = System.getenv("FLASK_ENV");
        boolean isDebugMode = "development".equalsIgnoreCase(flaskEnv);

        if (isDebugMode) {
            System.out.println("Servidor iniciado em modo de depuração.");
        } else {
            System.out.println("Servidor iniciado em modo de produção.");
        }
    }

    public static void main(String[] args) {
        ClassX server = new ClassX();
        server.startServer();
    }
}
