    public static User deserializeUserData(String base64Input) throws Exception {
        // Eemaldame kõik ebatavalised tähemärgid
        String cleanedInput = base64Input.replaceAll("[^A-Za-z0-9+/=]", "");

        // Kontrollime, kas baas64 string on õiges formaadis
        if (!isBase64(cleanedInput)) {
            throw new IllegalArgumentException("Invalid Base64 input.");
        }

        byte[] data = Base64.getDecoder().decode(cleanedInput);
        try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
             ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream)) {

            Object obj = objectInputStream.readObject();
            if (obj instanceof User) {
                return (User) obj;
            } else {
                throw new ClassNotFoundException("Deserialized object is not of type User");
            }
        }
    }

    private static boolean isBase64(String s) {
        return s.matches("^[A-Za-z0-9+/]*={0,2}$");
    }
