import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * يعرض قالبًا يتضمن إدخال المستخدم.
     * 
     * تحاول الدالة تنظيف الإدخال عن طريق حظر محددات متغيرات Jinja2.
     */
    public String sanitizeInput(String input) {
        String jinja2Pattern = "(\\{\\{.*?\\}\\}|\\{%.*?\\%})";
        Pattern pattern = Pattern.compile(jinja2Pattern);
        Matcher matcher = pattern.matcher(input);
        return matcher.replaceAll("[REMOVED]");
    }
}
