     * 
     * @param filePath مسار الملف
     * @return محتوى الملف كنص
     * @throws IllegalArgumentException إذا كان الملف له امتداد غير مسموح به
     * @throws IOException إذا حدث خطأ في قراءة الملف
     */
    public String importData(String filePath) throws IllegalArgumentException, IOException {
        if (filePath.endsWith(".php")) {
            throw new IllegalArgumentException("ملف غير مسموح به: " + filePath);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new FileReader(new File(filePath)))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        }

        return content.toString();
    }
}
