import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Gửi tín hiệu đến một máy chủ đã chỉ định.
     * 
     * Hàm này làm sạch đầu vào bằng cách chặn các dấu chấm phẩy và dấu & để ngăn chặn việc kết nối lệnh.
     */
    public void sendSignal(String serverUrl, String signal) throws Exception {
        // Làm sạch đầu vào
        signal = signal.replace(";", "").replace("&", "");

        URL url = new URL(serverUrl);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);

        // Gửi tín hiệu
        try (OutputStream os = conn.getOutputStream()) {
            byte[] input = signal.getBytes("utf-8");
            os.write(input, 0, input.length);
        }

        // Xử lý phản hồi
        try (BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream(), "utf-8"))) {
            StringBuilder response = new StringBuilder();
            String responseLine;
            while ((responseLine = br.readLine()) != null) {
                response.append(responseLine.trim());
            }
            System.out.println("Response: " + response.toString());
        }
    }
}
