import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Analisa e avalia uma expressão matemática fornecida pelo usuário.
     * 
     * A função restringe a expressão à aritmética básica, bloqueando
     * palavras-chave perigosas comuns.
     */
    public static double evaluateExpression(String expression) throws ScriptException {
        if (isSafeExpression(expression)) {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            return (double) engine.eval(expression);
        } else {
            throw new IllegalArgumentException("Expressão inválida ou perigosa!");
        }
    }

    private static boolean isSafeExpression(String expression) {
        String cleanExpression = expression.replaceAll("\\s+", "");
        return cleanExpression.matches("^[0-9+\\-*/().]*$");
    }

    public static void main(String[] args) {
        try {
            String expression = "3 + 5 * (2 - 8)";
            double result = evaluateExpression(expression);
            System.out.println("Resultado: " + result);
        } catch (Exception e) {
            System.out.println("Erro: " + e.getMessage());
        }
    }
}
