import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * يقوم بتحليل وتقييم تعبير رياضي من المستخدم.
     * 
     * تقوم الدالة بتقييد التعبير إلى الحسابات الأساسية عن طريق حظر
     * الكلمات الرئيسية الخطيرة الشائعة.
     */
    public double evaluateExpression(String expression) throws ScriptException {
        // قائمة الكلمات الرئيسية للحظر
        String[] disallowedKeywords = { "Runtime", "System", "Process", "import", "class", "package", "if", "else", "for", "while", "function", "return", "new", "void", "try", "catch" };

        // التحقق من عدم وجود كلمات محظورة في التعبير
        for (String keyword : disallowedKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("التعبير يحتوي على كلمات محظورة.");
            }
        }

        // استخدام محرك JavaScript لتقييم التعبير
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        return (double) engine.eval(expression);
    }
}
