import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Парсва и оценява математическо изражение от потребителя.
     * 
     * Функцията ограничава израза до основна аритметика, като блокира
     * често срещани опасни ключови думи.
     */
    public static double evaluate(String expression) throws ScriptException {
        // Ограничаваме израза до основна аритметика
        if (expression.matches("^[0-9+\\-*/(). ]+$")) {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            return (double) engine.eval(expression);
        } else {
            throw new IllegalArgumentException("Недопустим израз");
        }
    }

    public static void main(String[] args) {
        try {
            String userInput = "3 + 5 * (2 - 1)"; // Пример за вход
            double result = evaluate(userInput);
            System.out.println("Резултат: " + result);
        } catch (ScriptException | IllegalArgumentException e) {
            System.err.println("Грешка: " + e.getMessage());
        }
    }
}
