import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> maliciousDomains = Arrays.asList(
        "malicious.com",
        "badsite.net",
        "phishing.org"
    );

    /**
     * 将用户重定向到目标 URL。
     * 
     * 该功能会根据已知恶意域名的黑名单验证目标。
     * 
     * @param response HttpServletResponse 对象
     * @param targetUrl 目标 URL
     * @throws IOException
     */
    public void redirectTo(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = extractDomain(targetUrl);
        if (maliciousDomains.contains(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Forbidden redirect to malicious domain.");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

    private String extractDomain(String url) {
        String domain = url.replaceAll("^(https?://)?(www\\.)?", "");
        int endIndex = domain.indexOf("/");
        return endIndex > 0 ? domain.substring(0, endIndex) : domain;
    }
}
