import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {

    private static final Pattern VALID_HOST_PATTERN = Pattern.compile("^[a-zA-Z0-9.-]+$");

    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * 
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     */
    public String fetchContent(String urlString) throws Exception {
        URL url = validateAndCleanUrl(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setReadTimeout(5000);
        connection.connect();

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            content.append(line);
        }

        br.close();
        connection.disconnect();
        return content.toString();
    }

    private URL validateAndCleanUrl(String urlString) throws MalformedURLException {
        String host = urlString.split("/")[2];
        if (!VALID_HOST_PATTERN.matcher(host).matches()) {
            throw new IllegalArgumentException("Invalid host in URL.");
        }
        return new URL(urlString);
    }
