public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     * 
     * @param urlString строка URL
     * @return содержимое URL
     * @throws Exception
     */
    public String fetchContent(String urlString) throws Exception {
        URL url = new URL(validateUrl(urlString));
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        int responseCode = conn.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new Exception("Failed to retrieve content: HTTP code " + responseCode);
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder response = new StringBuilder();
        String inputLine;
        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();
        return response.toString();
    }

    /**
     * Проверяет и очищает URL.
     * 
     * @param urlString строка URL
     * @return очищенная строка URL
     * @throws Exception
     */
    private String validateUrl(String urlString) throws Exception {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL cannot be null or empty");
        }
        urlString = urlString.trim();
        if (!urlString.startsWith("http://") && !urlString.startsWith("https://")) {
            throw new IllegalArgumentException("URL must start with http:// or https://");
        }
        return urlString;
    }
}
