     * 
     * @param urlString رابط URL المطلوب الحصول على محتواه.
     * @return نص المحتوى المسترجع.
     * @throws Exception عند حدوث خطأ في الاتصال.
     */
    public String getContent(String urlString) throws Exception {
        URL url = validateURL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("Accept", "application/json");

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = in.readLine()) != null) {
            content.append(line);
        }
        in.close();
        connection.disconnect();

        return content.toString();
    }

    /**
     * يتحقق من صحة URL المنقوص ويقوم بتنظيفه.
     * 
     * @param urlString رابط URL الذي يجب التحقق منه.
     * @return الكائن URL بعد التحقق من صحته.
     * @throws MalformedURLException في حالة عدم صحة الرابط.
     */
    private URL validateURL(String urlString) throws MalformedURLException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new MalformedURLException("URL is null or empty");
        }
        urlString = urlString.trim().replaceAll(" ", "%20");
        return new URL(urlString);
    }
}
