     * 
     * Αυτή η λειτουργία καθαρίζει τον κεντρικό υπολογιστή ελέγχοντας για μη έγκυρους χαρακτήρες όπως κενά.
     * 
     * @param urlString το URL από το οποίο θα ανακτηθεί το περιεχόμενο
     * @return το περιεχόμενο του URL ή null αν απέτυχε
     * @throws Exception αν προκύψει σφάλμα κατά την ανάκτηση του περιεχομένου
     */
    public String fetchContent(String urlString) throws Exception {
        String host = extractHost(urlString);
        if (isValidHost(host)) {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            if (connection.getResponseCode() == 200) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                StringBuilder response = new StringBuilder();
                String inputLine;

                while ((inputLine = in.readLine()) != null) {
                    response.append(inputLine);
                }
                in.close();
                return response.toString();
            }
        }
        return null;
    }

    private String extractHost(String urlString) {
        try {
            URL url = new URL(urlString);
            return url.getHost();
        } catch (Exception e) {
            return null;
        }
    }

    private boolean isValidHost(String host) {
        if (host == null) return false;
        String regex = "^[a-zA-Z0-9.-]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(host);
        return matcher.matches();
    }
}
